The same network in Rust: use zombienet_sdk::{NetworkConfigBuilder, NetworkConfigExt}; #[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> { let network = NetworkConfigBuilder::new() .with_relaychain(|r| { r.with_chain("rococo-local") .with_default_command("polkadot") .with_validator(|v| v.with_name("alice")) .with_validator(|v| v.with_name("bob")) }) .build()? .spawn_native() .await?; let alice = network.get_node("alice")?; println!("Alice WS: {}", alice.ws_uri()); tokio::signal::ctrl_c().await?; Ok(())
}

