use zombienet_sdk::{NetworkConfigBuilder, NetworkConfigExt}; #[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> { let network = NetworkConfigBuilder::new() .with_relaychain(|r| { r.with_chain("rococo-local") .with_default_command("polkadot") .with_validator(|v| v.with_name("alice")) .with_validator(|v| v.with_name("bob")) }) .with_parachain(|p| { p.with_id(1000) .with_collator(|c| c.with_name("collator-1000").with_command("polkadot-parachain")) }) .with_parachain(|p| { p.with_id(2000) .with_collator(|c| c.with_name("collator-2000").with_command("polkadot-parachain")) }) .with_hrmp_channel(|h| h.with_sender(1000).with_recipient(2000)) .with_hrmp_channel(|h| h.with_sender(2000).with_recipient(1000)) .build() .unwrap() .spawn_native() .await?; Ok(())
}
